<?php
/**
 * SaaS Retail/E-commerce patch updater for the provided app(6).zip project.
 * Command: php update_retail_saas.php --dry-run
 * Command: php update_retail_saas.php --migrate --seed
 * Source-file backups only. Always back up your database independently.
 */
if(PHP_SAPI!=='cli'){http_response_code(403);exit('CLI only');}
$root=__DIR__;
if(!is_file($root.'/artisan')||!is_dir($root.'/app')||!is_dir($root.'/database')){fwrite(STDERR,"Place the updater in your Laravel root next to artisan.\n");exit(2);}
if(!function_exists('gzdecode')){fwrite(STDERR,"PHP zlib extension is required.\n");exit(2);}
$encoded='';$raw=base64_decode($encoded,true);$patch=$raw===false?null:json_decode(gzdecode($raw)?:'',true);
if(!$patch || !isset($patch['manifest'],$patch['files'])){fwrite(STDERR,"Patch payload is invalid.\n");exit(2);}
$dry=in_array('--dry-run',$argv,true);$force=in_array('--force',$argv,true);$migrate=in_array('--migrate',$argv,true);$seed=in_array('--seed',$argv,true);
$status=[];$conflicts=[];$bytesToApply=[];
foreach($patch['manifest'] as $rel=>$version){
 if(str_contains($rel,'..')||!preg_match('~^(?:RETAIL_ECOMMERCE_SETUP\.md|(app|bootstrap|database|routes|resources|tests)/[A-Za-z0-9_./-]+)$~D',$rel)){fwrite(STDERR,"Unsafe file path: $rel\n");exit(3);}
 $bytes=base64_decode($patch['files'][$rel]??'',true);
 if($bytes===false||hash('sha256',$bytes)!==$version['new']){fwrite(STDERR,"Patch checksum mismatch: $rel\n");exit(3);}
 $bytesToApply[$rel]=$bytes;
 $target=$root.'/'.str_replace('/',DIRECTORY_SEPARATOR,$rel);$existing=is_file($target)?hash_file('sha256',$target):null;
 if($existing===$version['new']){$status[$rel]='already applied';continue;}
 if($existing!==null && in_array($existing,$version['old'],true)){$status[$rel]='update';continue;}
 if($existing===null && $version['allow_missing']){$status[$rel]='new';continue;}
 $status[$rel]='CONFLICT';$conflicts[]=$rel;
}
foreach(['new','update','already applied','CONFLICT'] as $s){echo str_pad($s,18).': '.count(array_filter($status,fn($v)=>$v===$s))."\n";}
if($conflicts){echo "Conflicting source files:\n";foreach($conflicts as $rel)echo "  - $rel\n";}
if($dry){echo "Dry run: no changes applied.\n";exit(count($conflicts)>0?2:0);}
if($conflicts&&!$force){fwrite(STDERR,"Aborted: edited files not overwritten. Inspect changes or use --force after making backups.\n");exit(2);}
$apply=array_filter($status,fn($s)=>$s!=='already applied');
if($apply){
 $backup=$root.'/storage/app/retail_updates/'.date('Ymd_His').'_'.bin2hex(random_bytes(4));
 if(!is_dir($backup)&&!mkdir($backup,0775,true)&&!is_dir($backup)){fwrite(STDERR,"Cannot create backup directory.\n");exit(3);}
 $restore=[];
 // Back up EVERY existing destination before changing ANY file.
 foreach($apply as $rel=>$kind){$dest=$root.'/'.str_replace('/',DIRECTORY_SEPARATOR,$rel);$exists=is_file($dest);$restore[$rel]=['existed'=>$exists,'checksum'=>$exists?hash_file('sha256',$dest):null];
  if($exists){$save=$backup.'/'.str_replace('/',DIRECTORY_SEPARATOR,$rel);$dir=dirname($save);if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir))exit("Backup directory error\n");if(!copy($dest,$save))exit("Backup copy error: $rel\n");}
 }
 file_put_contents($backup.'/restore.json',json_encode($restore,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));
 foreach($apply as $rel=>$kind){$dest=$root.'/'.str_replace('/',DIRECTORY_SEPARATOR,$rel);$dir=dirname($dest);if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir))exit("Directory error: $rel\n");
  if(file_put_contents($dest,$bytesToApply[$rel],LOCK_EX)===false || hash_file('sha256',$dest)!==$patch['manifest'][$rel]['new'])exit("Write error: $rel\n");
 }
 echo 'Updated '.count($apply)." files; source backup: $backup\n";
}else echo "All files are up to date.\n";
function artisan(string $arg):void{global $root;$cmd=escapeshellarg(PHP_BINARY).' '.escapeshellarg($root.'/artisan').' '.$arg;echo "Running php artisan $arg\n";passthru($cmd,$exit);if($exit!==0){fwrite(STDERR,"Artisan command failed ($exit). Source backup is available; database migrations are NOT automatically rolled back.\n");exit($exit?:1);}}
if($migrate)artisan('migrate --force');
if($seed){echo "NOTICE: ModuleMenuSeeder updates category mapping. DATABASE backup required.\n";artisan('db:seed --class=ModuleMenuSeeder --force');artisan('db:seed --class=SubscriptionPlanSeeder --force');}
if(is_file($root.'/vendor/autoload.php'))artisan('optimize:clear');
echo "Patch completed. Run your Laravel feature tests and verify actual integration credentials before using live payments. Remove updater after use.\n";
